INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Aries', '', 'Nền tảng gia đình được đánh dấu bởi sự độc lập, năng lượng tiên phong và nhu cầu tự chủ mạnh mẽ trong không gian riêng.', 'Bạn muốn làm chủ ngôi nhà của mình. Bạn có thể rời gia đình sớm để tự lập hoặc tạo dựng gia đình theo cách riêng, đầy năng động.', 'Tinh thần tự lập mạnh mẽ, khả năng xây dựng tổ ấm bằng ý chí riêng và sức mạnh bảo vệ gia đình quyết liệt.', 'Xung đột gia đình do tính nóng nảy, khó thỏa hiệp trong không gian chung và bất ổn do luôn muốn thay đổi.', 'Gia đình là nơi bạn thể hiện sự mạnh mẽ nhất. Bạn cần người bạn đời tôn trọng không gian cá nhân và sự năng động tại nhà.', 'Học cách tạo sự bình yên tại nhà thay vì biến nó thành chiến trường. Nuôi dưỡng sự kiên nhẫn với các thành viên gia đình.', ARRAY['Nhà 4', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Taurus', '', 'Nền tảng gia đình xoay quanh sự ổn định, tiện nghi vật chất và truyền thống. Nhà là nơi trú ẩn an toàn và đầy ắp giác quan.', 'Bạn đầu tư rất nhiều vào ngôi nhà — trang trí đẹp, bếp ấm áp, vườn xanh. Bạn gắn bó sâu sắc với nơi mình sinh ra và lớn lên.', 'Khả năng tạo dựng tổ ấm sang trọng, ấm cúng, tính ổn định gia đình và mối liên kết sâu sắc với truyền thống gia tộc.', 'Bám víu nhà cửa và tài sản, kháng cự thay đổi nơi ở và khó chấp nhận khi gia đình phải chuyển biến.', 'Bạn tạo không gian sống tuyệt vời cho gia đình. Bạn cần người bạn đời chia sẻ tình yêu với sự thoải mái tại nhà.', 'Hiểu rằng nhà không chỉ là tòa nhà vật lý. Học cách mang theo cảm giác an toàn bên trong dù ở bất kỳ đâu.', ARRAY['Nhà 4', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Gemini', '', 'Nền tảng gia đình gắn liền với giao tiếp, sự đa dạng và bầu không khí trí tuệ sôi động.', 'Gia đình bạn có thể đã chuyển nhà nhiều lần hoặc luôn tràn ngập sách vở, cuộc trò chuyện. Bạn cần một ngôi nhà kích thích trí tuệ.', 'Bầu không khí gia đình cởi mở, khả năng thích ứng với nhiều môi trường sống và giao tiếp gia đình phong phú.', 'Thiếu ổn định tại nhà, quá nhiều thay đổi trong môi trường sống và khó tạo cảm giác "bén rễ" sâu sắc.', 'Bạn biến ngôi nhà thành trung tâm giao lưu. Bạn cần người bạn đời biết trò chuyện và giữ cho không gian sống luôn mới mẻ.', 'Tạo dựng cảm giác ổn định nội tâm dù cuộc sống bên ngoài luôn thay đổi. Tìm sự bình yên trong tâm trí thay vì chỉ ở nơi chốn.', ARRAY['Nhà 4', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Cancer', '', 'Nền tảng gia đình là trung tâm tuyệt đối của cuộc sống, đậm đặc tình cảm, sự nuôi dưỡng và ký ức thiêng liêng.', 'Bạn gắn bó cực kỳ sâu sắc với gia đình và nguồn cội. Ngôi nhà là thánh đường cảm xúc — nơi bạn tìm kiếm sự an toàn và chữa lành.', 'Bản năng nuôi dưỡng gia đình phi thường, khả năng tạo dựng tổ ấm đầy tình yêu và trực giác mạnh mẽ về nhu cầu người thân.', 'Bám víu quá khứ gia đình, khó rời bỏ ngôi nhà tuổi thơ và để nỗi đau gia đình chi phối hiện tại.', 'Gia đình là tất cả. Bạn cần người bạn đời hiểu và tôn trọng tầm quan trọng tuyệt đối của gia đình trong cuộc sống bạn.', 'Học cách xây dựng gia đình mới trong khi trân trọng nguồn cội. Đừng để ký ức quá khứ cản trở sự phát triển hiện tại.', ARRAY['Nhà 4', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Leo', '', 'Nền tảng gia đình gắn liền với niềm tự hào, sự sáng tạo và mong muốn tạo ra một tổ ấm đáng tự hào, rực rỡ.', 'Bạn muốn ngôi nhà mình là nơi ấn tượng nhất — trang trí lộng lẫy, tiệc tùng hoành tráng. Bạn tự hào sâu sắc về dòng họ.', 'Khả năng biến ngôi nhà thành cung điện, niềm tự hào gia đình mạnh mẽ và tinh thần hào phóng, ấm áp tại nhà.', 'Áp đặt quá mức trong gia đình, cần được chú ý tại nhà và biến ngôi nhà thành sân khấu phô trương.', 'Bạn là trung tâm gia đình, là nguồn năng lượng tích cực. Bạn cần người bạn đời cùng tự hào về tổ ấm chung.', 'Nhà không cần hoàn hảo để đáng yêu. Học cách tìm niềm vui trong sự giản dị và cho phép các thành viên gia đình cũng tỏa sáng.', ARRAY['Nhà 4', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Virgo', '', 'Nền tảng gia đình xoay quanh trật tự, sự phục vụ và chú ý tỉ mỉ đến mọi khía cạnh cuộc sống tại nhà.', 'Nhà bạn luôn ngăn nắp, sạch sẽ và được tổ chức hoàn hảo. Bạn chăm sóc gia đình qua những hành động thực tế: nấu ăn lành mạnh, dọn dẹp chu đáo.', 'Kỹ năng quản lý gia đình xuất sắc, tạo môi trường sống lành mạnh và chăm sóc sức khỏe gia đình tận tâm.', 'Quá khắt khe về vệ sinh và trật tự tại nhà, phê bình gia đình về những lỗi nhỏ và khó thư giãn trong không gian riêng.', 'Bạn chăm sóc gia đình qua hành động thực tế. Bạn cần người bạn đời hiểu và chia sẻ tiêu chuẩn cao về cuộc sống tại nhà.', 'Đừng biến nhà thành nơi làm việc. Cho phép sự hỗn loạn nhỏ tồn tại và tập trung vào niềm vui gia đình thay vì sự hoàn hảo.', ARRAY['Nhà 4', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Libra', '', 'Nền tảng gia đình hướng tới sự hài hòa, thẩm mỹ và bầu không khí thanh bình tại nhà. Ngôi nhà là tác phẩm nghệ thuật sống.', 'Bạn đầu tư rất nhiều để ngôi nhà đẹp và hài hòa. Bạn ghét xung đột gia đình và luôn đóng vai trò hòa giải giữa các thành viên.', 'Khả năng tạo không gian sống đẹp đẽ, hòa bình gia đình và tài ngoại giao trong xử lý mâu thuẫn nội bộ.', 'Tránh né xung đột gia đình cần thiết, hy sinh nhu cầu cá nhân để giữ hòa khí và phụ thuộc cảm xúc vào bầu không khí gia đình.', 'Bạn cần sự hài hòa tuyệt đối tại nhà. Bạn tìm kiếm người bạn đời chia sẻ cảm nhận thẩm mỹ và mong muốn sống hòa bình.', 'Đôi khi xung đột gia đình là cần thiết cho sự phát triển. Học cách đối mặt và giải quyết vấn đề thay vì che đậy.', ARRAY['Nhà 4', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Scorpio', '', 'Nền tảng gia đình mang chiều sâu tâm lý mãnh liệt, bí mật gia tộc và sức mạnh chuyển hóa sâu sắc.', 'Gia đình bạn có thể mang những bí mật lớn hoặc trải qua biến cố sâu sắc. Bạn có mối liên kết tâm lý mãnh liệt với nguồn cội và ngôi nhà.', 'Sức bật phi thường sau mọi biến cố gia đình, trực giác sâu sắc về động lực gia đình và khả năng chữa lành vết thương gia tộc.', 'Bí mật gia đình chưa được giải quyết, xu hướng kiểm soát trong gia đình và khó buông bỏ những tổn thương từ tuổi thơ.', 'Tổ ấm là nơi bạn bộc lộ sự thật sâu kín nhất. Bạn cần người bạn đời đủ mạnh mẽ để đối mặt với chiều sâu cảm xúc gia đình.', 'Đối mặt với bóng tối gia đình thay vì chôn vùi. Sự chữa lành bắt đầu khi bạn cho phép ánh sáng chiếu vào những góc khuất.', ARRAY['Nhà 4', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Sagittarius', '', 'Nền tảng gia đình hướng tới tự do, triết lý sống và tinh thần phiêu lưu. Nhà có thể ở nhiều nơi trên thế giới.', 'Bạn có thể lớn lên trong gia đình đa văn hóa hoặc di chuyển nhiều. Ngôi nhà lý tưởng là nơi mở rộng tầm nhìn, đầy sách và kỷ niệm du lịch.', 'Tầm nhìn rộng mở về gia đình, khả năng tạo tổ ấm ở bất kỳ đâu và tinh thần cởi mở, lạc quan trong bầu không khí gia đình.', 'Bồn chồn không yên một chỗ, khó cam kết với một nơi ở cố định và đôi khi bỏ bê trách nhiệm gia đình vì ham khám phá.', 'Bạn cần tự do cả trong gia đình. Bạn tìm kiếm người bạn đời sẵn sàng cùng phiêu lưu và không giam giữ bạn tại nhà.', 'Nhà không phải nhà tù — nhưng cam kết với một nơi chốn cũng là dạng tự do. Học cách bén rễ mà vẫn giữ đôi cánh.', ARRAY['Nhà 4', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Capricorn', '', 'Nền tảng gia đình xây dựng trên kỷ luật, truyền thống và cấu trúc vững chắc. Nhà là pháo đài của sự nghiêm túc và trách nhiệm.', 'Bạn có thể lớn lên trong gia đình nghiêm khắc hoặc gánh vác trách nhiệm gia đình sớm. Bạn xây dựng tổ ấm như một di sản lâu bền.', 'Trách nhiệm gia đình mạnh mẽ, khả năng xây dựng nền tảng gia đình vững chắc và tính kỷ luật trong quản lý gia đình.', 'Bầu không khí gia đình quá nghiêm khắc, thiếu sự ấm áp cảm xúc tại nhà và áp lực phải thành công vì gia đình.', 'Bạn xem gia đình là trách nhiệm thiêng liêng. Bạn cần người bạn đời chia sẻ giá trị truyền thống và cùng xây dựng tương lai vững chắc.', 'Cho phép niềm vui và sự vui tươi tồn tại trong nhà. Trách nhiệm quan trọng nhưng gia đình cũng cần tiếng cười.', ARRAY['Nhà 4', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Aquarius', '', 'Nền tảng gia đình mang tính phi truyền thống, độc đáo và hướng tới sự tự do cá nhân trong không gian chung.', 'Gia đình bạn có thể rất khác biệt so với chuẩn mực — cấu trúc gia đình đặc biệt, quy tắc riêng hoặc bầu không khí rất dân chủ, bình đẳng.', 'Tư duy cách mạng về cấu trúc gia đình, sự bình đẳng trong quan hệ gia đình và khả năng tạo không gian sống sáng tạo.', 'Sự xa cách cảm xúc trong gia đình, quá độc lập đến mức cô lập và khó chấp nhận vai trò gia đình truyền thống.', 'Bạn xem gia đình như nhóm bạn bè thay vì cấu trúc truyền thống. Bạn cần người bạn đời tôn trọng không gian cá nhân tại nhà.', 'Sự kết nối cảm xúc với gia đình cũng quan trọng như sự tự do trí tuệ. Học cách mở lòng với người thân yêu.', ARRAY['Nhà 4', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Pisces', '', 'Nền tảng gia đình thấm đượm cảm xúc, tâm linh và sự mơ mộng. Nhà là thánh đường tâm linh và nơi trú ẩn khỏi thế giới.', 'Bạn có mối liên kết tâm linh sâu sắc với gia đình. Ngôi nhà lý tưởng gần nước, yên tĩnh và đầy nghệ thuật. Bạn hấp thụ năng lượng gia đình rất mạnh.', 'Trực giác gia đình phi thường, khả năng tạo bầu không khí chữa lành tại nhà và lòng hy sinh vô điều kiện cho gia đình.', 'Ranh giới mờ nhạt trong gia đình, hấp thụ nỗi đau gia đình như bọt biển và xu hướng lý tưởng hóa hoặc tô hồng ký ức gia đình.', 'Bạn cần tổ ấm bình yên, tĩnh lặng. Bạn tìm kiếm người bạn đời thấu hiểu chiều sâu cảm xúc và chia sẻ nhu cầu tâm linh tại nhà.', 'Xây dựng ranh giới rõ ràng với gia đình. Bạn có thể yêu thương sâu sắc mà vẫn bảo vệ sức khỏe cảm xúc của chính mình.', ARRAY['Nhà 4', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Aries', '', 'Sáng tạo và tình yêu được thúc đẩy bởi đam mê mãnh liệt, sự phấn khích và tinh thần chinh phục liên tục.', 'Bạn yêu như chiến binh — nhanh chóng, mãnh liệt và đầy nhiệt huyết. Bạn thích các hoạt động sáng tạo mang tính cạnh tranh và mạo hiểm.', 'Năng lượng sáng tạo dồi dào, sự can đảm trong tình yêu và khả năng khởi xướng các dự án nghệ thuật đầy hứng khởi.', 'Yêu nhanh chán nhanh, thiếu kiên nhẫn với quá trình sáng tạo lâu dài và xu hướng coi tình yêu như trò chơi chinh phục.', 'Bạn cần sự phấn khích liên tục trong tình yêu. Bạn bị thu hút bởi người mạnh mẽ, độc lập và dám thử thách bạn.', 'Học rằng tình yêu bền vững cần sự kiên nhẫn, không chỉ đam mê ban đầu. Nuôi dưỡng sáng tạo qua kỷ luật lẫn cảm hứng.', ARRAY['Nhà 5', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Taurus', '', 'Sáng tạo và tình yêu gắn liền với giác quan, sự ổn định và thẩm mỹ tinh tế. Niềm vui đến từ những điều đẹp đẽ, cụ thể.', 'Bạn yêu chậm rãi nhưng sâu sắc và bền vững. Bạn thể hiện sáng tạo qua nghệ thuật thị giác, âm nhạc, ẩm thực hoặc thủ công mỹ nghệ.', 'Sự kiên nhẫn trong sáng tạo, tình yêu bền vững trung thành và khả năng tạo ra những tác phẩm nghệ thuật đẹp đẽ, bền lâu.', 'Sở hữu trong tình yêu, kháng cự thay đổi trong mối quan hệ lãng mạn và bám víu vào sự thoải mái quen thuộc.', 'Bạn là người yêu trung thành, lãng mạn kiểu cổ điển. Bạn thể hiện tình yêu qua quà tặng, bữa ăn ngon và sự chăm sóc chu đáo.', 'Đón nhận những trải nghiệm sáng tạo mới ngoài vùng an toàn. Tình yêu cũng cần sự tươi mới để không trở nên đơn điệu.', ARRAY['Nhà 5', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Gemini', '', 'Sáng tạo và tình yêu được nuôi dưỡng bởi trí tuệ, sự đa dạng và giao tiếp. Niềm vui đến từ học hỏi và chia sẻ ý tưởng.', 'Bạn yêu bằng trí tuệ trước rồi mới bằng trái tim. Bạn thích viết lách, chơi chữ, và tham gia nhiều hoạt động sáng tạo cùng lúc.', 'Tư duy sáng tạo linh hoạt, khả năng giao tiếp tình cảm thú vị và tài năng kể chuyện thu hút người nghe.', 'Hời hợt trong tình yêu, chán nhanh và khó cam kết với một người hoặc một dự án sáng tạo duy nhất.', 'Bạn cần người yêu là tri kỷ trí tuệ. Cuộc trò chuyện thú vị quan trọng hơn sự lãng mạn truyền thống.', 'Phát triển chiều sâu cảm xúc trong tình yêu. Trí tuệ là nền tảng nhưng trái tim cũng cần được nuôi dưỡng.', ARRAY['Nhà 5', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Cancer', '', 'Sáng tạo và tình yêu thấm đượm cảm xúc sâu sắc, bản năng nuôi dưỡng và mong muốn tạo dựng kết nối tình cảm bền chặt.', 'Bạn yêu với toàn bộ trái tim và bản năng bảo vệ. Sáng tạo của bạn mang chiều sâu cảm xúc — thơ ca, nấu ăn, chăm sóc người khác là nghệ thuật.', 'Trực giác sáng tạo mạnh mẽ, khả năng kết nối cảm xúc sâu sắc trong tình yêu và tài năng nghệ thuật giàu cảm xúc.', 'Quá nhạy cảm trong tình yêu, sợ bị từ chối đến mức không dám mở lòng và dễ bám víu quá khứ lãng mạn.', 'Bạn chăm sóc người yêu như chăm sóc gia đình. Bạn cần cảm giác an toàn cảm xúc trước khi bộc lộ tình cảm.', 'Mở lòng cho tình yêu mới dù đã từng bị tổn thương. Cảm xúc mạnh mẽ là sức mạnh, không phải điểm yếu.', ARRAY['Nhà 5', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Leo', '', 'Sáng tạo và tình yêu là sân khấu chính trong cuộc đời — rực rỡ, hào phóng và đầy kịch tính. Bạn sinh ra để tỏa sáng và yêu đời.', 'Bạn là ngôi sao sáng trong tình yêu và sáng tạo. Bạn yêu nhiệt thành, sáng tạo đầy tự tin và luôn muốn tạo ấn tượng mạnh mẽ.', 'Sức sáng tạo phi thường, sức hút lãng mạn cuốn hút và khả năng biến mọi trải nghiệm thành kỷ niệm đáng nhớ.', 'Cần được ngưỡng mộ trong tình yêu, kịch tính hóa cảm xúc và cái tôi lớn có thể che khuất nhu cầu của đối phương.', 'Bạn yêu hào phóng, trung thành và muốn được ngưỡng mộ. Bạn tìm kiếm người bạn đời sáng giá, xứng đáng đứng cạnh.', 'Tình yêu thực sự không cần khán giả. Học cách yêu trong sự giản dị và cho phép đối phương cũng tỏa sáng.', ARRAY['Nhà 5', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Virgo', '', 'Sáng tạo và tình yêu được tiếp cận với sự tỉ mỉ, phân tích và mong muốn hoàn thiện. Niềm vui đến từ sự cải thiện liên tục.', 'Bạn thể hiện sáng tạo qua sự hoàn hảo trong chi tiết. Trong tình yêu, bạn kỹ tính, chậm rãi nhưng khi yêu thì vô cùng tận tụy.', 'Sự tinh tế trong sáng tạo, tình yêu chân thành thể hiện qua hành động phục vụ và khả năng cải thiện mọi dự án.', 'Quá cầu toàn trong tình yêu, phê bình đối phương và khó buông lỏng để tận hưởng niềm vui đơn thuần.', 'Bạn yêu bằng hành động — chăm sóc sức khỏe, giúp đỡ thực tế, hỗ trợ trong cuộc sống hàng ngày. Bạn cần người hiểu ngôn ngữ tình yêu này.', 'Đừng chờ hoàn hảo mới bắt đầu yêu hoặc sáng tạo. Sự không hoàn hảo là một phần tuyệt đẹp của cuộc sống.', ARRAY['Nhà 5', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Libra', '', 'Sáng tạo và tình yêu hướng tới sự hài hòa, thẩm mỹ và quan hệ đối tác. Niềm vui đến từ vẻ đẹp và sự chia sẻ.', 'Bạn bị thu hút bởi vẻ đẹp trong mọi dạng — nghệ thuật, thời trang, âm nhạc. Trong tình yêu, bạn lãng mạn, duyên dáng và luôn hướng tới sự cân bằng.', 'Cảm nhận thẩm mỹ tinh tế, sức hút lãng mạn tự nhiên và khả năng tạo ra các tác phẩm nghệ thuật hài hòa, đẹp đẽ.', 'Lý tưởng hóa tình yêu, do dự trong việc chọn đối phương và dễ thỏa hiệp bản thân chỉ để giữ mối quan hệ hòa bình.', 'Bạn tìm kiếm tình yêu như tác phẩm nghệ thuật — đẹp đẽ, cân bằng và hoàn hảo. Bạn cần người bạn đời tinh tế và biết trân trọng vẻ đẹp.', 'Tình yêu thực tế có cả ánh sáng lẫn bóng tối. Học cách chấp nhận sự không hoàn hảo trong mối quan hệ.', ARRAY['Nhà 5', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Scorpio', '', 'Sáng tạo và tình yêu mang chiều sâu mãnh liệt, đam mê cháy bỏng và sức mạnh chuyển hóa. Bạn yêu toàn bộ hoặc không yêu.', 'Bạn yêu mãnh liệt, sâu sắc và đầy bí ẩn. Sáng tạo của bạn khám phá những chủ đề sâu thẳm — sự sống, cái chết, tình dục, quyền lực.', 'Đam mê sáng tạo phi thường, sự gắn kết tình cảm mãnh liệt và khả năng chạm đến chiều sâu cảm xúc trong nghệ thuật.', 'Ghen tuông trong tình yêu, xu hướng kiểm soát đối phương và khó buông bỏ những mối tình đã qua.', 'Bạn tìm kiếm sự gắn kết tâm hồn tuyệt đối. Tình yêu nửa vời không bao giờ đủ — bạn muốn hòa nhập hoàn toàn với đối phương.', 'Học cách yêu mà không kiểm soát. Sự tin tưởng và tự do trong tình yêu tạo ra sự gắn kết sâu sắc hơn bất kỳ sự sở hữu nào.', ARRAY['Nhà 5', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Sagittarius', '', 'Sáng tạo và tình yêu là cuộc phiêu lưu vĩ đại — tự do, lạc quan và đầy triết lý. Niềm vui đến từ khám phá và mở rộng tầm nhìn.', 'Bạn yêu tự do trong tình cảm, thích những cuộc tình phiêu lưu và thể hiện sáng tạo qua du lịch, triết học, giáo dục.', 'Tinh thần lạc quan trong tình yêu, sáng tạo mang tầm nhìn lớn và khả năng truyền cảm hứng qua niềm đam mê sống.', 'Sợ cam kết, quá thẳng thắn gây tổn thương và xu hướng lý tưởng hóa tình yêu đến mức phi thực tế.', 'Bạn cần tự do trong tình yêu. Bạn bị thu hút bởi người chia sẻ tình yêu phiêu lưu, tri thức và ý nghĩa cuộc sống.', 'Cam kết không phải nhà tù. Tình yêu sâu sắc có thể là cuộc phiêu lưu vĩ đại nhất trong cuộc đời bạn.', ARRAY['Nhà 5', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Capricorn', '', 'Sáng tạo và tình yêu được tiếp cận nghiêm túc, có kỷ luật và hướng tới thành tựu lâu dài. Niềm vui đến từ sự thành công.', 'Bạn thận trọng trong tình yêu, chọn đối phương như chọn đối tác kinh doanh. Sáng tạo của bạn mang tính chiến lược, có mục tiêu rõ ràng.', 'Sự kiên trì trong sáng tạo, tình yêu bền vững và có trách nhiệm, khả năng xây dựng sự nghiệp nghệ thuật lâu dài.', 'Quá nghiêm túc trong niềm vui, khó buông lỏng để tận hưởng và đánh giá tình yêu qua tiêu chuẩn thực dụng.', 'Bạn yêu chậm nhưng chắc, coi trọng sự cam kết. Bạn thể hiện tình yêu qua hành động bảo đảm tương lai chung.', 'Cho phép bản thân vui đùa và yêu không tính toán đôi khi. Niềm vui không cần phải có mục đích hay kết quả.', ARRAY['Nhà 5', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Aquarius', '', 'Sáng tạo và tình yêu mang tính phi truyền thống, độc đáo và hướng tới tương lai. Niềm vui đến từ sự khác biệt và đổi mới.', 'Bạn có phong cách yêu khác biệt — coi trọng tình bạn trong tình yêu, cần không gian tự do và thể hiện sáng tạo qua công nghệ hoặc ý tưởng cách mạng.', 'Tư duy sáng tạo đột phá, cách tiếp cận tình yêu cởi mở và khả năng tạo ra những tác phẩm nghệ thuật mang tính xã hội.', 'Lạnh lùng cảm xúc trong tình yêu, quá xa cách và khó biểu đạt tình cảm sâu sắc theo cách truyền thống.', 'Bạn cần người yêu đồng thời là tri kỷ trí tuệ. Bạn yêu theo cách độc đáo và cần đối phương chấp nhận sự khác biệt này.', 'Tình yêu không chỉ ở trong đầu. Học cách kết nối cảm xúc sâu sắc bên cạnh sự kết nối trí tuệ.', ARRAY['Nhà 5', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Pisces', '', 'Sáng tạo và tình yêu là trải nghiệm tâm linh, lãng mạn siêu việt và đầy trí tưởng tượng. Niềm vui đến từ sự hòa nhập cảm xúc.', 'Bạn là người lãng mạn nhất — yêu say đắm, mơ mộng và đầy cảm hứng nghệ thuật. Sáng tạo đến từ trực giác, giấc mơ và cảm xúc sâu thẳm.', 'Trí tưởng tượng sáng tạo vô biên, tình yêu sâu sắc và hy sinh, khả năng chạm đến tâm hồn người khác qua nghệ thuật.', 'Ảo tưởng trong tình yêu, chiếu lý tưởng hóa lên đối phương và dễ bị tổn thương khi thực tế không khớp với mơ mộng.', 'Bạn tìm kiếm tình yêu siêu việt, tâm linh. Bạn yêu vô điều kiện nhưng có thể đánh mất bản thân trong đối phương.', 'Phân biệt giữa tình yêu thực sự và ảo tưởng lãng mạn. Giữ chân trên mặt đất trong khi trái tim bay trong mây.', ARRAY['Nhà 5', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Aries', '', 'Công việc và sức khỏe được tiếp cận với năng lượng tiên phong, sự quyết đoán và tinh thần cạnh tranh mạnh mẽ.', 'Bạn làm việc nhanh, hiệu quả và thích dẫn đầu. Bạn ưu tiên các bài tập thể dục cường độ cao và không thể chịu nổi công việc nhàm chán, lặp lại.', 'Năng lượng làm việc dồi dào, tinh thần khởi nghiệp trong công việc và khả năng hoàn thành nhiệm vụ nhanh chóng.', 'Kiệt sức vì làm việc quá sức, xung đột với đồng nghiệp và bỏ bê sức khỏe cho đến khi gặp vấn đề nghiêm trọng.', 'Trong môi trường làm việc, bạn thích lãnh đạo hơn là tuân theo. Bạn cần đồng nghiệp tôn trọng tốc độ và sự độc lập của bạn.', 'Cân bằng giữa cường độ làm việc và nghỉ ngơi. Sức khỏe bền vững cần sự kiên nhẫn, không chỉ sự mãnh liệt.', ARRAY['Nhà 6', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Taurus', '', 'Công việc và sức khỏe gắn liền với sự ổn định, kiên nhẫn và phương pháp tiếp cận thực tế, bền vững.', 'Bạn làm việc ổn định, đáng tin cậy và kiên trì. Bạn chú trọng sức khỏe qua ăn uống lành mạnh, tập thể dục đều đặn và giữ thói quen cố định.', 'Sự bền bỉ trong công việc, thói quen sức khỏe ổn định và khả năng hoàn thành dự án dài hạn với chất lượng cao.', 'Ngại thay đổi phương pháp làm việc, quá chậm chạp trong thích ứng và dễ bỏ bê sức khỏe vì lười thay đổi thói quen.', 'Bạn là đồng nghiệp đáng tin cậy nhất. Bạn cần môi trường làm việc ổn định, thoải mái và tôn trọng nhịp độ cá nhân.', 'Đón nhận sự linh hoạt trong công việc và thói quen sức khỏe. Đôi khi thay đổi phương pháp mang lại kết quả tốt hơn.', ARRAY['Nhà 6', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Gemini', '', 'Công việc và sức khỏe cần sự đa dạng, kích thích trí tuệ và linh hoạt. Thói quen cần luôn mới mẻ để duy trì.', 'Bạn thích làm nhiều việc cùng lúc, cần sự thay đổi liên tục trong công việc. Sức khỏe gắn liền với trạng thái tinh thần — căng thẳng ảnh hưởng cơ thể.', 'Khả năng đa nhiệm xuất sắc, sự thông minh trong giải quyết vấn đề công việc và linh hoạt thích ứng với mọi thay đổi.', 'Khó tập trung vào một nhiệm vụ, căng thẳng thần kinh ảnh hưởng sức khỏe và thói quen sức khỏe không nhất quán.', 'Bạn cần môi trường làm việc đa dạng, kích thích. Bạn giao tiếp tốt với đồng nghiệp nhưng có thể gây phân tán.', 'Phát triển thói quen sức khỏe ổn định dù bạn thích sự thay đổi. Tâm trí yên tĩnh là nền tảng sức khỏe thể chất.', ARRAY['Nhà 6', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Cancer', '', 'Công việc và sức khỏe gắn liền với cảm xúc, bản năng nuôi dưỡng và nhu cầu cảm thấy an toàn trong môi trường làm việc.', 'Bạn làm việc tốt nhất khi cảm thấy được chăm sóc và thuộc về. Sức khỏe phản ánh trạng thái cảm xúc — stress ảnh hưởng trực tiếp đến dạ dày và tiêu hóa.', 'Bản năng chăm sóc đồng nghiệp, trực giác công việc mạnh mẽ và khả năng tạo môi trường làm việc ấm áp.', 'Cảm xúc chi phối hiệu suất công việc, khó tách rời công việc và cuộc sống cá nhân, dễ lo lắng về sức khỏe.', 'Bạn chăm sóc đồng nghiệp như gia đình. Bạn cần môi trường làm việc an toàn cảm xúc và sự công nhận sự chăm sóc của bạn.', 'Xây dựng ranh giới cảm xúc trong công việc. Chăm sóc bản thân trước khi chăm sóc người khác — không thể rót từ ly rỗng.', ARRAY['Nhà 6', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Leo', '', 'Công việc và sức khỏe gắn liền với niềm tự hào, sáng tạo và mong muốn được công nhận trong môi trường làm việc.', 'Bạn muốn nổi bật trong công việc và được ngưỡng mộ về năng lực. Bạn chú trọng ngoại hình, sức khỏe tim mạch và duy trì hình ảnh khỏe mạnh.', 'Tinh thần lãnh đạo trong công việc, sức sống năng động và khả năng truyền cảm hứng cho đồng nghiệp.', 'Cần được chú ý quá mức tại nơi làm việc, cái tôi lớn trong nhiệm vụ nhóm và bỏ bê sức khỏe khi bận rộn.', 'Bạn là ngôi sao nơi làm việc. Bạn cần sự công nhận và cơ hội tỏa sáng. Đồng nghiệp kính trọng nhưng đôi khi ghen tị.', 'Sự khiêm tốn trong công việc cũng là sức mạnh. Chia sẻ ánh đèn và công nhận đóng góp của người khác.', ARRAY['Nhà 6', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Virgo', '', 'Công việc và sức khỏe là lĩnh vực bạn tỏa sáng nhất — tỉ mỉ, hiệu quả và luôn cải tiến. Sự hoàn hảo là mục tiêu tối thượng.', 'Bạn là nhân viên lý tưởng — chi tiết, chăm chỉ và đáng tin cậy. Bạn rất quan tâm sức khỏe, có thể theo chế độ ăn uống và tập luyện nghiêm ngặt.', 'Năng lực tổ chức phi thường, đạo đức làm việc mạnh mẽ và sự chú ý đến sức khỏe toàn diện.', 'Cầu toàn đến mức kiệt sức, lo lắng thái quá về sức khỏe và khó ủy thác công việc vì không tin ai làm tốt bằng mình.', 'Bạn phục vụ đồng nghiệp tận tâm nhưng đòi hỏi cao. Bạn cần môi trường làm việc trật tự, sạch sẽ và hiệu quả.', 'Đủ tốt cũng là tốt. Đừng để cầu toàn phá hủy sức khỏe và niềm vui trong công việc.', ARRAY['Nhà 6', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Libra', '', 'Công việc và sức khỏe cần sự cân bằng, hài hòa và thẩm mỹ. Bạn làm việc tốt nhất trong môi trường hòa bình, đẹp đẽ.', 'Bạn thích môi trường làm việc thanh lịch, hợp tác và công bằng. Sức khỏe gắn liền với sự cân bằng — thận, da, và hệ thống hormone.', 'Kỹ năng hợp tác xuất sắc, khả năng tạo hòa bình nơi làm việc và cảm nhận thẩm mỹ trong mọi sản phẩm công việc.', 'Do dự trong quyết định công việc, tránh xung đột cần thiết và để ý kiến người khác chi phối phương pháp làm việc.', 'Bạn là cầu nối hòa giải tại nơi làm việc. Bạn cần sự hài hòa trong nhóm và ghét bầu không khí căng thẳng.', 'Đôi khi cần đưa ra quyết định một mình. Sức khỏe cần sự cân bằng thực sự, không chỉ tránh xung đột.', ARRAY['Nhà 6', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Scorpio', '', 'Công việc và sức khỏe được tiếp cận với cường độ, chiều sâu và mong muốn chuyển hóa hoàn toàn. Bạn làm việc với sự tận tụy tuyệt đối.', 'Bạn đào sâu vào công việc với sự ám ảnh và quyết tâm. Sức khỏe gắn liền với hệ sinh sản, giải độc và khả năng tự chữa lành.', 'Sự tập trung phi thường trong công việc, khả năng phát hiện vấn đề ẩn giấu và sức mạnh phục hồi sức khỏe đáng kinh ngạc.', 'Ám ảnh với công việc, khó buông bỏ kiểm soát và bỏ bê sức khỏe cho đến khi đến điểm khủng hoảng.', 'Bạn là đồng nghiệp đáng gờm — tận tụy, bí mật và cực kỳ hiệu quả. Bạn đòi hỏi sự trung thành và cam kết tương đương.', 'Buông bỏ sự kiểm soát ám ảnh trong công việc. Sức khỏe cần sự cân bằng giữa cường độ và nghỉ ngơi.', ARRAY['Nhà 6', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Sagittarius', '', 'Công việc và sức khỏe cần sự tự do, ý nghĩa và không gian mở rộng. Bạn không thể chịu nổi công việc bó buộc, nhàm chán.', 'Bạn thích công việc liên quan đến du lịch, giáo dục hoặc mang ý nghĩa triết học. Sức khỏe tốt nhất khi hoạt động ngoài trời và sống tích cực.', 'Tinh thần lạc quan trong công việc, thể chất năng động và khả năng tìm ý nghĩa sâu sắc trong nhiệm vụ hàng ngày.', 'Bỏ bê chi tiết, quá tự tin vào sức khỏe dẫn đến chủ quan và khó chịu với thói quen và quy tắc cứng nhắc.', 'Bạn mang năng lượng lạc quan đến nơi làm việc. Bạn cần tự do và cơ hội phát triển — công việc tù túng khiến bạn héo mòn.', 'Chi tiết cũng quan trọng. Kết hợp tầm nhìn lớn với sự chú ý đến thực tế hàng ngày để đạt hiệu quả tối đa.', ARRAY['Nhà 6', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Capricorn', '', 'Công việc và sức khỏe được xây dựng trên kỷ luật sắt, tham vọng và phương pháp tiếp cận bài bản. Đây là vị trí của sự chuyên nghiệp cao nhất.', 'Bạn là người làm việc chăm chỉ nhất, luôn hướng tới thăng tiến. Sức khỏe gắn liền với xương, khớp, da — bạn cần vận động đều đặn nhưng hợp lý.', 'Đạo đức làm việc phi thường, khả năng xây dựng sự nghiệp bền vững và tính kỷ luật trong chăm sóc sức khỏe.', 'Workaholic, bỏ bê sức khỏe tinh thần, quá nghiêm khắc với bản thân và đồng nghiệp, dễ kiệt sức.', 'Bạn là trụ cột nơi làm việc. Đồng nghiệp kính trọng nhưng đôi khi sợ sự nghiêm khắc của bạn.', 'Công việc quan trọng nhưng sức khỏe là nền tảng. Cho phép bản thân nghỉ ngơi mà không cảm thấy tội lỗi.', ARRAY['Nhà 6', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Aquarius', '', 'Công việc và sức khỏe cần sự đổi mới, tự do trí tuệ và phương pháp phi truyền thống. Bạn cải cách cách làm việc.', 'Bạn thích công việc liên quan đến công nghệ, khoa học hoặc cải cách xã hội. Sức khỏe được quan tâm qua phương pháp mới lạ, tiên tiến.', 'Tư duy đổi mới trong công việc, cách tiếp cận sức khỏe tiến bộ và khả năng cải thiện hệ thống làm việc.', 'Nổi loạn với quy tắc công việc, thói quen sức khỏe thất thường và khó tuân theo chỉ dẫn y tế truyền thống.', 'Bạn là nhà cách mạng tại nơi làm việc. Bạn cần tự do trí tuệ và ghét sự kiểm soát vi mô.', 'Đổi mới cần nền tảng ổn định. Kết hợp phương pháp truyền thống và hiện đại trong cả công việc và sức khỏe.', ARRAY['Nhà 6', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Pisces', '', 'Công việc và sức khỏe chịu ảnh hưởng sâu sắc từ trực giác, cảm xúc và mong muốn phục vụ, chữa lành. Ranh giới dễ bị mờ nhạt.', 'Bạn thích công việc mang tính phục vụ, chữa lành hoặc nghệ thuật. Sức khỏe nhạy cảm với cảm xúc và môi trường — bạn dễ hấp thụ stress của người khác.', 'Lòng trắc ẩn trong phục vụ, trực giác mạnh mẽ trong chẩn đoán vấn đề và khả năng chữa lành tự nhiên.', 'Ranh giới yếu tại nơi làm việc, dễ bị lợi dụng, bỏ bê sức khỏe thể chất và trốn tránh nhiệm vụ khó chịu.', 'Bạn là đồng nghiệp đầy lòng trắc ẩn nhưng dễ kiệt sức vì chăm sóc người khác quá nhiều.', 'Thiết lập ranh giới rõ ràng trong công việc. Chăm sóc bản thân là điều kiện tiên quyết để phục vụ người khác hiệu quả.', ARRAY['Nhà 6', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
